def verify():
    assert 20000 * 2000 / (200 * 200000) == 1 and abs(200000 * 12e-6 * 50 - 120) < 1e-9
    assert abs(16e6 / (math.pi * 40 ** 3) - 79.58) < 0.01 and abs(10000 / (2 * math.pi * 1000 / 60) - 95.49) < 0.01
    Z = 50 * 100 ** 2 / 6; assert abs(Z - 83333.3) < 0.1 and abs(5e6 / Z - 60) < 1e-9 and abs(math.pi * 50 ** 3 / 32 - 12271.8) < 0.1
    assert 1.5 * 10000 / 5000 == 3 and abs(1000 * 1e9 / (3 * 2e5 * 1e6) - 1.6667) < 1e-4 and abs(1000 * 8e9 / (48 * 2e11) - 0.8333) < 1e-4
    assert math.hypot(30, 40) == 50 and abs(math.sqrt(100 ** 2 + 3 * 50 ** 2) - 132.29) < 0.01 and abs(math.hypot(50, 50) - 70.71) < 0.01
    assert abs(math.pi ** 2 * 2e11 / 2000 ** 2 / 1000 - 493.48) < 0.01 and abs(1e8 * 1000 / (2 * 100 * 2e5) - 2500) < 1e-9


if __name__ == "__main__":
    verify()
